previewCss:
.darma-loader-darma-b13-roulette-wheel { --accent: var(--loader-color, #b91c1c); --accent-2: var(--loader-secondary-color, #a16207); width: var(--loader-size, 100px); height: var(--loader-size, 100px); position: relative; display: grid; place-items: center; }
.darma-loader-darma-b13-roulette-wheel .darma-loader-darma-b13-roulette-wheel__wheel { position: relative; width: 100%; height: 100%; border-radius: 50%; background: repeating-conic-gradient(from 0deg, var(--accent) 0 15deg, color-mix(in srgb, #000 62%, var(--accent)) 15deg 30deg); box-shadow: inset 0 0 0 calc(var(--loader-size, 100px) * .05) var(--accent-2); animation: darma-loader-darma-b13-roulette-wheel-wheel-spin calc(var(--loader-speed, 1s) * 3.4) linear infinite; }
.darma-loader-darma-b13-roulette-wheel .darma-loader-darma-b13-roulette-wheel__wheel::after { content: ''; position: absolute; inset: 28%; border-radius: 50%; background: radial-gradient(circle at 40% 34%, color-mix(in srgb, #fff 32%, var(--accent-2)), color-mix(in srgb, #000 24%, var(--accent-2))); }
.darma-loader-darma-b13-roulette-wheel span { position: absolute; top: 50%; left: 50%; width: 9%; height: 9%; margin: -4.5% 0 0 -4.5%; border-radius: 50%; background: radial-gradient(circle at 36% 32%, #fff, #cbd5e1); animation: darma-loader-darma-b13-roulette-wheel-ball-orbit calc(var(--loader-speed, 1s) * 1.3) linear infinite; }
@keyframes darma-loader-darma-b13-roulette-wheel-wheel-spin { to { transform: rotate(360deg); } }
@keyframes darma-loader-darma-b13-roulette-wheel-ball-orbit { from { transform: rotate(0deg) translateY(calc(var(--loader-size, 100px) * -.39)); } to { transform: rotate(-360deg) translateY(calc(var(--loader-size, 100px) * -.39)); } }

